// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createLink, getLink, deleteLinks } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Request Body
    const linksPostRequestBody: string = `{
        "collection": {
            "name": "Unorganized"
        },
        "name": "testbot status readback",
        "tags": [],
        "url": "https://testbot.example.com/archive-status-readback"
    }`;

    const linksPostResponse = await createLink(client, headers, linksPostRequestBody, 200);
    expect(linksPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe("testbot status readback");
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe("https://testbot.example.com/archive-status-readback");
    expect(getResponseValue(linksPostResponse, "response.type"), 'type').toBe("url");
    expect(getResponseValue(linksPostResponse, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);
    expect(getResponseValue(linksPostResponse, "response.archiveStatus"), 'archiveStatus').toBe("pending");
    expect(getResponseValue(linksPostResponse, "response.archiveJobId"), 'archiveJobId').toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i);

    const linkId = getResponseValue(linksPostResponse, "response.id");

    // archiveStatus transitions 'pending' -> 'completed' after the worker and 'failed' on error,
    // so the link must still carry it when it is read back.
    const linksLinksGetResponse = await getLink(client, headers, linkId, 200);
    expect(linksLinksGetResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksLinksGetResponse, "response.id"), 'id').toBe(linkId);
    expect(getResponseValue(linksLinksGetResponse, "response.name"), 'name').toBe("testbot status readback");
    expect(getResponseValue(linksLinksGetResponse, "response.url"), 'url').toBe("https://testbot.example.com/archive-status-readback");
    expect(getResponseValue(linksLinksGetResponse, "response.type"), 'type').toBe("url");
    expect(getResponseValue(linksLinksGetResponse, "response.archiveStatus"), 'archiveStatus').toBe("pending");

    const linksDeleteResponse = await deleteLinks(client, headers, [linkId], 200);
    expect(linksDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksDeleteResponse, "response.count"), 'count').toBe(1);
});
